/** The editable inputs, by nutrient. Sodium has none: it scales with the rest, unseen. */
const MACRO_INPUTS = {
    calories: 'cal-serving',
    protein_g: 'protein-serving',
    carbs_g: 'carbs-serving',
    fat_g: 'fat-serving',
    fiber_g: 'fiber-serving',
    sugar_g: 'sugar-serving',
} as const satisfies Partial<Record<keyof ServingValues, string>>;

type EditableNutrient = keyof typeof MACRO_INPUTS;

const AMOUNT_INVALID = 'Enter an amount above 0';

export class FoodServingForm extends HTMLElement {
    private _data: FoodServingFormData | null = null;
    private _editable = false;
    private _initialized = false;
    /**
     * Story 368: edit mode scales from a fixed baseline — baseline × amount ÷
     * baseline amount — never from the previous keystroke. Rescaling the inputs
     * on every keystroke, rounded each time, made typing "200" over a 150 g
     * entry pass through 2 g and 20 g and lose small macros to rounding; the
     * baseline moves only when the user edits a macro.
     */
    private _baseline: { amount: number; values: ServingValues } | null = null;
    /** The unrounded values at `_valuesAmount`; the inputs show these rounded. */
    private _values: ServingValues | null = null;
    private _valuesAmount = 0;

    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
    }

    static get observedAttributes(): string[] {
        return ['editable'];
    }

    attributeChangedCallback(name: string, _old: string | null, value: string | null): void {
        if (name === 'editable') {
            this._editable = value !== null;
            if (this._initialized) this.rebuild();
        }
    }

    connectedCallback(): void {
        if (this.hasOwnProperty('data')) {
            const value = (this as any).data;
            delete (this as any).data;
            this._data = value;
        }
        this._editable = this.hasAttribute('editable');
        this.rebuild();
        this._initialized = true;
    }

    set data(value: FoodServingFormData) {
        this._data = value;
        // Story 372 (pwa-nutrition-23): before connect there is no form to fill; `rebuild` will.
        if (this._initialized) this.populate();
    }

    /**
     * Read current serving values and amount from the form. `servingAmount`
     * is returned in BASE UNITS (grams in weight mode; servings × baseAmount
     * otherwise) — the unit every persisted amount uses (story 192). The
     * displayed serving count is a UI affordance only.
     *
     * Null while the amount is empty or not above 0 — and the field says so.
     * Story 368: an empty amount used to read as 0.1 and log a 0.1 g entry.
     */
    getCurrentValues(): { servingAmount: number; serving: ServingValues } | null {
        const inputAmount = this.readAmount();
        if (inputAmount === null) {
            this.amountInput().reportValidity();
            return null;
        }
        const servingAmount = this._data?.servingByWeight === false
            ? inputAmount * (this._data.baseAmount > 0 ? this._data.baseAmount : 1)
            : inputAmount;

        if (this._editable) {
            this.adoptEditedMacros();
            return { servingAmount, serving: this.valuesAt(inputAmount) };
        }

        // Read-only mode: recalculate from per100g or use current data
        return { servingAmount, serving: this.calculateServing(inputAmount) };
    }

    private amountInput(): HTMLInputElement {
        return this.shadowRoot!.getElementById('serving-size') as HTMLInputElement;
    }

    /** The typed amount, or null when it is empty, unparseable or not above 0 (flagged on the field). */
    private readAmount(): number | null {
        const input = this.amountInput();
        const amount = Number.parseFloat(input.value);
        const valid = Number.isFinite(amount) && amount > 0;
        input.setCustomValidity(valid ? '' : AMOUNT_INVALID);
        return valid ? amount : null;
    }

    /** A macro input as a value: blank is unknown, not 0 (story 368). */
    private readMacroInput(key: EditableNutrient): Nutrient {
        const parsed = Number.parseFloat((this.shadowRoot!.getElementById(MACRO_INPUTS[key]) as HTMLInputElement).value);
        return Number.isFinite(parsed) ? parsed : null;
    }

    /**
     * Fold any macro the user changed into the model and make it the new
     * baseline. A changed input is one that no longer shows the model's value —
     * so a value set without an `input` event (autofill, a test) still counts.
     */
    private adoptEditedMacros(): void {
        if (!this._values) return;
        let edited = false;
        for (const key of Object.keys(MACRO_INPUTS) as EditableNutrient[]) {
            const input = this.shadowRoot!.getElementById(MACRO_INPUTS[key]) as HTMLInputElement;
            if (input.value === this.formatNutritionValue(this._values[key])) continue;
            this._values[key] = this.readMacroInput(key);
            edited = true;
        }
        if (edited) this._baseline = { amount: this._valuesAmount, values: { ...this._values } };
    }

    /** The baseline scaled to `amount`, unrounded. */
    private valuesAt(amount: number): ServingValues {
        if (!this._baseline || this._baseline.amount <= 0) return this._values ?? this.unknownServing();
        return scaleNutrients(this._baseline.values, amount / this._baseline.amount);
    }

    private unknownServing(): ServingValues {
        return { calories: null, protein_g: null, carbs_g: null, fat_g: null, fiber_g: null, sugar_g: null, sodium_mg: null };
    }

    private rebuild(): void {
        const shadow = this.shadowRoot!;
        shadow.adoptedStyleSheets = [styles];
        shadow.replaceChildren();
        const tmpl = this._editable ? editableTemplate : readOnlyTemplate;
        shadow.appendChild(tmpl.content.cloneNode(true));
        this.wireEvents();
        if (this._data) this.populate();
    }

    private wireEvents(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('serving-size')!.addEventListener('input', () => this.onServingChange());
        shadow.getElementById('serving-size')!.addEventListener('change', () => this.onServingChange());
        shadow.getElementById('step-down')!.addEventListener('click', () => this.adjustServing(-1));
        shadow.getElementById('step-up')!.addEventListener('click', () => this.adjustServing(1));

        if (this._editable) {
            // A macro edit moves the baseline, and the per-100g reference follows it.
            for (const id of Object.values(MACRO_INPUTS)) {
                shadow.getElementById(id)?.addEventListener('input', () => {
                    this.adoptEditedMacros();
                    this.refreshPer100gFromInputs();
                });
            }
        }
    }

    private populate(): void {
        const data = this._data;
        if (!data) return;
        const shadow = this.shadowRoot!;

        // Serving label
        const label = shadow.getElementById('serving-label')!;
        label.textContent = data.servingByWeight ? 'Serving (g)' : 'Servings';

        // Serving amount
        const amountInput = this.amountInput();
        amountInput.value = this.formatAmount(data.servingAmount);
        amountInput.setCustomValidity('');

        // Macros
        this._baseline = { amount: data.servingAmount, values: { ...data.serving } };
        this._values = { ...data.serving };
        this._valuesAmount = data.servingAmount;
        this.renderServing(data.serving);

        // Per-100g reference (shown in both read-only and editable modes when per100g is available)
        const per100Section = shadow.getElementById('per100-section');
        if (per100Section) {
            if (data.per100g) {
                per100Section.hidden = false;
                const refLabel = shadow.getElementById('ref-label')!;
                refLabel.textContent = data.servingByWeight ? 'Per 100g' : 'Per serving';
                shadow.getElementById('cal-100')!.textContent = formatMacro(data.per100g.calories);
                shadow.getElementById('protein-100')!.textContent = formatMacro(data.per100g.protein_g);
                shadow.getElementById('carbs-100')!.textContent = formatMacro(data.per100g.carbs_g);
                shadow.getElementById('fat-100')!.textContent = formatMacro(data.per100g.fat_g);
            } else {
                per100Section.hidden = true;
            }
        }

        // Portion presets
        this.renderPortionPresets();
    }

    /**
     * Rebuild the per-100g display from the current macro inputs, so the
     * reference stays truthful while the user edits macros directly.
     */
    private refreshPer100gFromInputs(): void {
        const shadow = this.shadowRoot!;
        const per100Section = shadow.getElementById('per100-section') as HTMLElement | null;
        if (!per100Section || per100Section.hidden) return;
        if (!this._data?.servingByWeight || !this._values || this._valuesAmount <= 0) return;

        const per100 = scaleNutrients(this._values, 100 / this._valuesAmount);
        shadow.getElementById('cal-100')!.textContent = formatMacro(per100.calories);
        shadow.getElementById('protein-100')!.textContent = formatMacro(per100.protein_g);
        shadow.getElementById('carbs-100')!.textContent = formatMacro(per100.carbs_g);
        shadow.getElementById('fat-100')!.textContent = formatMacro(per100.fat_g);
    }

    private renderServing(serving: ServingValues): void {
        const shadow = this.shadowRoot!;
        if (this._editable) {
            // Preserve decimals so float-valued macros (e.g., 7.75g protein) survive a round-trip.
            (shadow.getElementById('cal-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.calories);
            (shadow.getElementById('protein-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.protein_g);
            (shadow.getElementById('carbs-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.carbs_g);
            (shadow.getElementById('fat-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.fat_g);
            (shadow.getElementById('fiber-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.fiber_g);
            (shadow.getElementById('sugar-serving') as HTMLInputElement).value = this.formatNutritionValue(serving.sugar_g);
        } else {
            shadow.getElementById('cal-serving')!.textContent = formatMacro(serving.calories);
            shadow.getElementById('protein-serving')!.textContent = formatMacro(serving.protein_g);
            shadow.getElementById('carbs-serving')!.textContent = formatMacro(serving.carbs_g);
            shadow.getElementById('fat-serving')!.textContent = formatMacro(serving.fat_g);
        }
    }

    private onServingChange(): void {
        // An empty or non-positive amount on the way to the next one (a
        // backspace) leaves the macros alone; the field is flagged.
        const amount = this.readAmount();
        if (amount === null) return;
        if (this._editable) {
            this.adoptEditedMacros();
            this._values = this.valuesAt(amount);
            this._valuesAmount = amount;
            this.renderServing(this._values);
            this.refreshPer100gFromInputs();
            return;
        }
        this.renderServing(this.calculateServing(amount));
    }

    private calculateServing(amount: number): ServingValues {
        const data = this._data;
        if (!data) return this.unknownServing();

        if (data.per100g && data.servingByWeight) return scaleNutrients(data.per100g, amount / 100);

        // Multiplier mode. `data.serving` is scaled to `data.servingAmount`
        // (the type's documented contract), so scale by the RATIO of the new
        // count to the initial count. Multiplying absolutely treated a
        // 2.5-serving default as ×2.5 on top of already-scaled macros (story 192).
        return scaleNutrients(data.serving, amount / (data.servingAmount > 0 ? data.servingAmount : 1));
    }

    private adjustServing(direction: 1 | -1): void {
        const input = this.amountInput();
        const current = Number.parseFloat(input.value) || 0;
        const step = this._data?.servingByWeight
            ? OpenFoodFactsService.getServingStep(current)
            : 1;
        input.value = this.formatAmount(Math.max(0.1, current + direction * step));
        this.onServingChange();
    }

    /** Story 399: "x2" multiplies the amount currently entered, so repeated taps compound (150 → 300 → 600). */
    private renderPortionPresets(): void {
        const container = this.shadowRoot!.getElementById('portion-presets')!;
        container.replaceChildren();
        const data = this._data;
        if (!data?.servingByWeight) return;

        const presets = OpenFoodFactsService.getPortionPresets();
        for (const preset of presets) {
            const btn = document.createElement('button');
            btn.className = 'preset-btn';
            btn.type = 'button';
            btn.textContent = `x${preset.multiplier}`;
            btn.addEventListener('click', () => {
                const input = this.amountInput();
                const current = Number.parseFloat(input.value) || 0;
                input.value = this.formatAmount(current * preset.multiplier);
                this.onServingChange();
            });
            container.appendChild(btn);
        }
    }

    /** For an input: rounded to 2 decimals, blank when unknown. */
    private formatNutritionValue(value: Nutrient): string {
        return value === null ? '' : Number(value.toFixed(2)).toString();
    }

    private formatAmount(value: number): string {
        return Number(value.toFixed(2)).toString();
    }
}

if (!customElements.get('food-serving-form')) {
    customElements.define('food-serving-form', FoodServingForm);
}
