import { computeSnapshotMacros, offDefaultServing, offNutritionToFoodItem } from '@motivation/shared';
import type { FoodItem, ConsumptionEntry, NewFoodItem } from '@motivation/shared';
import type { OFFProduct } from '../../../services/openfoodfacts.service.js';

/**
 * The nutrition-carrying half of a food row. A saved `FoodItem` has it; so does
 * a `NewFoodItem` that has not been saved yet — story 338's label draft, which
 * goes through the same review surface as an Open Food Facts product and so has
 * to feed the same form. Narrowing to the fields the form actually reads is what
 * lets both in without a cast.
 */
export type FoodNutrition = Pick<NewFoodItem,
    | 'base_amount' | 'base_unit' | 'default_serving_amount' | 'serving_label' | 'serving_quantity'
    | 'calories_per_base' | 'protein_g_per_base' | 'carbs_g_per_base' | 'fat_g_per_base'
    | 'fiber_g_per_base' | 'sugar_g_per_base' | 'sodium_mg_per_base'
>;

/**
 * A nutrient amount, or null when the source does not say. Story 368: unknown is
 * not 0 — the form used to fill every gap with 0, which logged "no data" as
 * "none" and showed a food without a label as 0 kcal, the same as water.
 */
export type Nutrient = number | null;

export interface ServingValues {
    calories: Nutrient;
    protein_g: Nutrient;
    carbs_g: Nutrient;
    fat_g: Nutrient;
    fiber_g: Nutrient;
    sugar_g: Nutrient;
    sodium_mg: Nutrient;
}

export const NUTRIENT_KEYS = ['calories', 'protein_g', 'carbs_g', 'fat_g', 'fiber_g', 'sugar_g', 'sodium_mg'] as const;

/** A finite number, or null — a stored NULL, an absent field and NaN are all "unknown". */
export function known(value: number | null | undefined): Nutrient {
    return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

/** Scale every known nutrient by `factor`; an unknown one stays unknown. */
export function scaleNutrients(values: ServingValues, factor: number): ServingValues {
    const scaled = {} as ServingValues;
    for (const key of NUTRIENT_KEYS) {
        const value = values[key];
        scaled[key] = value === null ? null : value * factor;
    }
    return scaled;
}

export interface FoodServingFormData {
    /** Per-100g base values for proportional recalculation. Null when only fixed-serving data is available. */
    per100g: ServingValues | null;
    /** Current serving nutrition (already scaled to servingAmount). */
    serving: ServingValues;
    /** Default serving amount — grams when servingByWeight is true, otherwise a multiplier. */
    servingAmount: number;
    /** True = grams mode with adaptive step sizes. False = multiplier mode (step = 1). */
    servingByWeight: boolean;
    /** Display label for multiplier mode (e.g. "1 serving"). */
    servingLabel?: string;
    /**
     * Base units per ONE serving (the food item's `base_amount`; 100 in the
     * per-100g modes). Persisted amounts (`consumption_entries.amount`,
     * `food_items.default_serving_amount`, meal-ingredient amounts) are ALWAYS
     * in base units system-wide; the multiplier shown in the UI is amount /
     * baseAmount. Treating a base-unit default as a raw multiplier is how an
     * untouched Chocomel save logged 20,500 kcal — story 192.
     */
    baseAmount: number;
}

function foodItemToPer100g(item: FoodNutrition): ServingValues | null {
    // FoodItem stores nutrient densities per `base_amount` in `base_unit`.
    // For weight-based foods (g) we can normalize directly to per-100g.
    // Volume-based and piece-based items have no per-100g representation.
    if (item.base_unit !== 'g' || !item.base_amount || item.base_amount <= 0) {
        return null;
    }
    // Story 373: a food row's nutrients for an amount come from one function, the one the
    // repositories snapshot entries with — this file had its own copy.
    return computeSnapshotMacros(item, 100);
}

export function offProductToFormData(product: OFFProduct): FoodServingFormData {
    const defaultGrams = offDefaultServing(product);
    // Story 369: the same per-100 g columns the saved row gets.
    const nutrition = offNutritionToFoodItem(product);
    return {
        per100g: computeSnapshotMacros(nutrition, 100),
        serving: computeSnapshotMacros(nutrition, defaultGrams),
        servingAmount: defaultGrams,
        servingByWeight: true,
        baseAmount: 100,
    };
}

/**
 * `initialAmount` overrides the food item's default — used when re-opening the
 * form for an already-chosen amount (e.g. editing an existing meal ingredient).
 */
export function foodItemToFormData(item: FoodNutrition, initialAmount?: number): FoodServingFormData {
    const per100g = foodItemToPer100g(item);
    if (per100g) {
        const fallbackGrams = item.default_serving_amount && item.default_serving_amount > 0
            ? Math.round(item.default_serving_amount)
            : item.serving_quantity && item.serving_quantity > 0
                ? Math.round(item.serving_quantity)
                : 100;
        const grams = initialAmount && initialAmount > 0 ? initialAmount : fallbackGrams;
        return {
            per100g,
            serving: computeSnapshotMacros(item, grams),
            servingAmount: grams,
            servingByWeight: true,
            baseAmount: 100,
        };
    }
    // Non-gram base_unit: per-base values represent one serving of
    // `base_amount` `base_unit` (e.g. one piece, 100ml). Persisted amounts
    // (default_serving_amount, initialAmount from entries/ingredients) are in
    // BASE UNITS — convert to the serving multiplier the form displays, and
    // scale the macros to it (story 192: 250ml default on a per-100ml item is
    // 2.5 servings, not 250).
    const baseAmount = item.base_amount > 0 ? item.base_amount : 1;
    const amountInBaseUnits = initialAmount && initialAmount > 0
        ? initialAmount
        : item.default_serving_amount && item.default_serving_amount > 0
            ? item.default_serving_amount
            : baseAmount; // one serving
    const multiplier = amountInBaseUnits / baseAmount;
    return {
        per100g: null,
        serving: computeSnapshotMacros(item, amountInBaseUnits),
        servingAmount: multiplier,
        servingByWeight: false,
        servingLabel: item.serving_label ?? `${item.base_amount} ${item.base_unit}`,
        baseAmount,
    };
}

/**
 * Build form data from an existing consumption entry combined with its referenced
 * food item. The entry already snapshots the macros at log time, and that
 * snapshot is what the form scales (DLR #108; story 368 — sodium used to be
 * re-derived from the food row as it is today). The food item only supplies the
 * per-100g reference shown beside it.
 */
export function consumptionEntryToFormData(entry: ConsumptionEntry, foodItem: FoodItem): FoodServingFormData {
    const serving: ServingValues = {
        calories: known(entry.calories),
        protein_g: known(entry.protein_g),
        carbs_g: known(entry.carbs_g),
        fat_g: known(entry.fat_g),
        fiber_g: known(entry.fiber_g),
        sugar_g: known(entry.sugar_g),
        sodium_mg: known(entry.sodium_mg),
    };
    const per100g = foodItemToPer100g(foodItem);
    if (per100g) {
        return {
            per100g,
            serving,
            servingAmount: entry.amount,
            servingByWeight: true,
            baseAmount: 100,
        };
    }
    // entry.amount is in base units; the form displays servings (story 192).
    const baseAmount = foodItem.base_amount > 0 ? foodItem.base_amount : 1;
    return {
        per100g: null,
        serving,
        servingAmount: entry.amount / baseAmount,
        servingByWeight: false,
        servingLabel: foodItem.serving_label ?? `${foodItem.base_amount} ${foodItem.base_unit}`,
        baseAmount,
    };
}

/**
 * Story 338 — fold what is on screen back into the draft before it is saved.
 *
 * The review surface exists so a misread nutrition table can be corrected, and
 * a correction that does not reach the saved row is not a correction. The OFF
 * path can get away without this (its numbers came from a database, and the
 * form is read-only there); a label read cannot, because the numbers came from
 * a model looking at a photograph.
 *
 * `base_amount` / `base_unit` are the draft's, never the form's: the form shows
 * a *serving*, the row stores a *density*, and story 192 is what happens when
 * those two are allowed to blur. So the serving on screen is divided back down
 * to one base unit's worth using the base the read established.
 */
export function applyReviewedServing(
    draft: NewFoodItem,
    values: { servingAmount: number; serving: ServingValues },
): NewFoodItem {
    if (!(values.servingAmount > 0) || !(draft.base_amount > 0)) return draft;

    /**
     * A field the read could not get stays unset unless the reviewer put a
     * number in it. Story 338's e2e caught the form turning "the photo did not
     * show the fibre row" into "the label says 0 g fibre"; since story 368 the
     * form keeps a blank as null, so a blank stays unset and a typed 0 is a 0.
     */
    const perBase = (v: Nutrient) => (v === null ? undefined : (v * draft.base_amount) / values.servingAmount);
    return {
        ...draft,
        default_serving_amount: values.servingAmount,
        calories_per_base: perBase(values.serving.calories),
        protein_g_per_base: perBase(values.serving.protein_g),
        carbs_g_per_base: perBase(values.serving.carbs_g),
        fat_g_per_base: perBase(values.serving.fat_g),
        fiber_g_per_base: perBase(values.serving.fiber_g),
        sugar_g_per_base: perBase(values.serving.sugar_g),
        sodium_mg_per_base: perBase(values.serving.sodium_mg),
    };
}
